// The UIKitML panels in public/ui are generated by scripts/ui/*.py. Run every generator into a
// temporary folder and check the committed files match, so an edit to a generated file (or a
// generator change without regenerating) fails here.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { parse, resolveKitComponentSets } from "@drawcall/uikitml";
import { afterAll, describe, expect, it } from "vitest";

const ROOT = path.resolve(__dirname, "../..");
const GENERATORS = readdirSync(path.join(ROOT, "scripts/ui")).filter((f) => f.startsWith("gen-") && f.endsWith(".py"));
const out = mkdtempSync(path.join(tmpdir(), "sl-ui-"));

afterAll(() => rmSync(out, { recursive: true, force: true }));

describe("generated UIKitML", () => {
  it("every public/ui file matches its generator", () => {
    for (const g of GENERATORS) execFileSync("python3", [path.join(ROOT, "scripts/ui", g), out], { stdio: "pipe" });
    const made = readdirSync(out).sort();
    const committed = readdirSync(path.join(ROOT, "public/ui")).filter((f) => f.endsWith(".uikitml")).sort();
    expect(made).toEqual(committed);
    for (const f of made) {
      expect(readFileSync(path.join(ROOT, "public/ui", f), "utf8"), f).toBe(readFileSync(path.join(out, f), "utf8"));
    }
  });

  it("every file parses with the UIKitML parser IWSDK uses (unknown properties or values fail the app's load)", () => {
    const componentSets = resolveKitComponentSets("horizon");
    for (const f of readdirSync(path.join(ROOT, "public/ui")).filter((x) => x.endsWith(".uikitml"))) {
      const r = parse(readFileSync(path.join(ROOT, "public/ui", f), "utf8"), { componentSets });
      expect(r.success ? [] : r.errors.map((e) => JSON.stringify(e)), f).toEqual([]);
    }
  });

  it("every file carries the shared stylesheet unchanged", () => {
    const common = execFileSync("python3", ["-c", "import sys; sys.stdout.write(__import__('ui_common').COMMON)"], {
      cwd: path.join(ROOT, "scripts/ui"),
      encoding: "utf8",
    });
    expect(common.length).toBeGreaterThan(500);
    for (const f of readdirSync(path.join(ROOT, "public/ui")).filter((x) => x.endsWith(".uikitml"))) {
      expect(readFileSync(path.join(ROOT, "public/ui", f), "utf8").includes(`<style>${common}`), f).toBe(true);
    }
  });
});
